ALTER TABLE "youtube_discovery_appearances" ADD COLUMN IF NOT EXISTS "query_builder_version" integer;
ALTER TABLE "youtube_discovery_appearances" DROP CONSTRAINT IF EXISTS "youtube_discovery_appearances_eligibility_check";
ALTER TABLE "youtube_discovery_appearances" ADD CONSTRAINT "youtube_discovery_appearances_eligibility_check" CHECK (("language_fit" is null and "duration_fit" is null and "eligibility_reason" is null and "query_builder_version" is null and "language_classifier_version" is null and "minimum_useful_duration_seconds" is null) OR ("language_fit" in ('vi','likely_vi','unknown','non_vi') and "duration_fit" in ('eligible','too_short','duration_unknown') and "eligibility_reason" = case when "duration_fit" = 'too_short' then 'too_short' when "duration_fit" = 'duration_unknown' then 'duration_unknown' when "language_fit" in ('vi','likely_vi') then 'eligible_vietnamese' when "eligibility_reason" = 'foreign_fallback' and "language_fit" in ('unknown','non_vi') then 'foreign_fallback' when "language_fit" = 'non_vi' then 'non_vietnamese' else 'language_unknown' end and "query_builder_version" between 1 and 2 and "language_classifier_version" = 1 and "minimum_useful_duration_seconds" between 180 and 86400));
